fn snake_to_camel(snake_str string) string {
	if snake_str == "schema_" {
		return "$schema"
	}
	if snake_str == "not_" {
		return "not"
	}
	components := snake_str.split("_")
	return components[0] + components[1..].map(it.title()).join("")
}

fn to_camel_case(data map[string]any, skip_keys []string = []) map[string]any {
	if data is map[string]any {
		mut result := map[string]any{}
		for k, v in data {
			if v != none {
				camel_key := snake_to_camel(k)
				if v is map[string]any && !skip_keys.contains(k) {
					result[camel_key] = to_camel_case(v, skip_keys)
				} else {
					result[camel_key] = v
				}
			}
		}
		return result
	}
	return data
}

fn camel_to_snake(camel_str string) string {
	snake_str := regex.replace_all_string(camel_str, "(.)([A-Z][a-z]+)", "$1_$2")
	return regex.replace_all_string(snake_str, "([a-z0-9])([A-Z])", "$1_$2").to_lower()
}

fn to_snake_case(data map[string]any) map[string]any {
	if data is map[string]any {
		mut result := map[string]any{}
		for k, v in data {
			snake_key := camel_to_snake(k)
			if v is map[string]any {
				result[snake_key] = to_snake_case(v)
			} else {
				result[snake_key] = v
			}
		}
		return result
	}
	return data
}

