struct StreamChunk {
	content string
	citations []AnswerResult
}

fn (c StreamChunk) has_data() bool {
	return c.content != none || c.citations != none
}

fn (c StreamChunk) str() string {
	mut output := ""
	if c.content != none {
		output += c.content
	}
	if c.citations != none {
		output += "\nCitations:"
		for source in c.citations {
			output += "\n$source"
		}
	}
	return output
}

