fn (r AnswerResponse) str() string {
	mut output := "Answer: $r.answer\n\nCitations:"
	for source in r.citations {
		output += "\nTitle: $source.title"
		output += "\nID: $source.id"
		output += "\nURL: $source.url"
		output += "\nPublished Date: $source.published_date"
		output += "\nAuthor: $source.author"
		output += "\nText: $source.text"
		output += "\n"
	}
	return output
}

struct StreamAnswerResponse {
	_raw_response http.Response
}

fn (r StreamAnswerResponse) _ensure_ok_status() {
	if r._raw_response.status_code != 200 {
		panic("Request failed with status code $r._raw_response.status_code: $r._raw_response.text")
	}
}

fn (r StreamAnswerResponse) iter() []StreamChunk {
	mut chunks := []StreamChunk{}
	for line in r._raw_response.iter_lines() {
		if line == "" {
			continue
		}
		decoded_line := line.decode("utf-8").removeprefix("data: ")
		mut chunk := map[string]any{}
		json.decode(decoded_line, &chunk) or { continue }

		mut content := none
		mut citations := none

		if chunk.contains("choices") && chunk["choices"] != [] {
			if chunk["choices"][0].contains("delta") {
				content = chunk["choices"][0]["delta"].get("content")
			}
		}

		if chunk.contains("citations") && chunk["citations"] != [] && chunk["citations"] != "null" {
			citations = []
			for s in chunk["citations"] {
				snake_s := to_snake_case(s)
				citations.append(AnswerResult{
					id: snake_s.get("id")
					url: snake_s.get("url")
					title: snake_s.get("title")
					published_date: snake_s.get("published_date")
					author: snake_s.get("author")
					text: snake_s.get("text")
				})
			}
		}

		stream_chunk := StreamChunk{content: content, citations: citations}
		if stream_chunk.has_data() {
			chunks.append(stream_chunk)
		}
	}
	return chunks
}

fn (r StreamAnswerResponse) close() {
	r._raw_response.close()
}

struct AsyncStreamAnswerResponse {
	_raw_response http.Response
}

fn (r AsyncStreamAnswerResponse) _ensure_ok_status() {
	if r._raw_response.status_code != 200 {
