fn (r AsyncStreamAnswerResponse) aiter() chan StreamChunk {
	ch := chan StreamChunk{}
	go fn() {
		defer close(ch)
		for line in r._raw_response.aiter_lines() {
			if line == "" {
				continue
			}
			decoded_line := line.removeprefix("data: ")
			mut chunk := map[string]any{}
			json.decode(decoded_line, &chunk) or { continue }

			mut content := none
			mut citations := none

			if chunk.contains("choices") && chunk["choices"] != [] {
				if chunk["choices"][0].contains("delta") {
					content = chunk["choices"][0]["delta"].get("content")
				}
			}

			if chunk.contains("citations") && chunk["citations"] != [] && chunk["citations"] != "null" {
				citations = []
				for s in chunk["citations"] {
					snake_s := to_snake_case(s)
					citations.append(AnswerResult{
						id: snake_s.get("id")
						url: snake_s.get("url")
						title: snake_s.get("title")
						published_date: snake_s.get("published_date")
						author: snake_s.get("author")
						text: snake_s.get("text")
					})
				}
			}

			stream_chunk := StreamChunk{content: content, citations: citations}
			if stream_chunk.has_data() {
				ch <- stream_chunk
			}
		}
	}()
	return ch
}

