fn nest_fields(original_dict map[string]any, fields_to_nest []string, new_key string) map[string]any {
	mut nested_dict := map[string]any{}
	for field in fields_to_nest {
		if original_dict.contains(field) {
			nested_dict[field] = original_dict.pop(field)
		}
	}
	original_dict[new_key] = nested_dict
	return original_dict
}

struct Exa {
	base_url string
	headers map[string]string
	websets WebsetsClient
	research ResearchClient
}

fn new_exa(api_key string, base_url string = "", user_agent string = none) Exa {
	if api_key == none {
		api_key = os.getenv("EXA_API_KEY")
		if api_key == none {
			panic("API key must be provided as an argument or in EXA_API_KEY environment variable")
		}
	}
	if user_agent == none {
		user_agent = "exa-py ${exa_py.utils._get_package_version()}"
	}
	return Exa{
		base_url: base_url
		headers: {
			"x-api-key": api_key
			"User-Agent": user_agent
			"Content-Type": "application/json"
		}
		websets: new_websets_client()
		research: new_research_client()
	}
}

fn (e Exa) request(endpoint string, data any = none, method string = "POST", params map[string]any = none, headers map[string]string = none) any {
	mut json_data := none
	if data is string {
		json_data = data
	} else {
		json_data = json.encode(data)
	}
	needs_streaming := (data != none && data.get("stream")) || (params != none && params.get("stream") == "true")
	mut request_headers := e.headers.clone()
	if headers != none {
		request_headers.update(headers)
	}
	mut res := none
	if method.to_upper() == "GET" {
		if needs_streaming {
			res = http.get(e.base_url + endpoint, headers: request_headers, params: params, stream: true)
			return res
		} else {
			res = http.get(e.base_url + endpoint, headers: request_headers, params: params)
		}
	} else if method.to_upper() == "POST" {
		if needs_streaming {
			res = http.post(e.base_url + endpoint, data: json_data, headers: request_headers, stream: true)
			return res
		} else {
			res = http.post(e.base_url + endpoint, data: json_data, headers: request_headers)
		}
	} else if method.to_upper() == "PATCH" {
		res = http.patch(e.base_url + endpoint, data: json_data, headers: request_headers)
	} else if method.to_upper() == "DELETE" {
		res = http.delete(e.base_url + endpoint, headers: request_headers)
	} else {
		panic("Unsupported HTTP method: $method")
	}
	if res.status_code >= 400 {
		panic("Request failed with status code $res.status_code: $res.text")
	}
	return res.json()
}

fn (e Exa) search(query string, contents any = none, num_results int = none, include_domains []string = none, exclude_domains []string = none, start_crawl_date string = none, end_crawl_date string = none, start_published_date string = none, end_published_date string = none, include_text []string = none, exclude_text []string = none, type string = none, category string = none, flags []string = none, moderation bool = none, user_location string = none) SearchResponse[Result] {
	mut options := map[string]any{}
	if query != none { options["query"] = query }
	if contents != none { options["contents"] = contents }
	if num_results != none { options["num_results"] = num_results }
	if include_domains != none { options["include_domains"] = include_domains }
	if exclude_domains != none { options["exclude_domains"] = exclude_domains }
	if start_crawl_date != none { options["start_crawl_date"] = start_crawl_date }
	if end_crawl_date != none { options["end_crawl_date"] = end_crawl_date }
	if start_published_date != none { options["start_published_date"] = start_published_date }
	if end_published_date != none { options["end_published_date"] = end_published_date }
	if include_text != none { options["include_text"] = include_text }
	if exclude_text != none { options["exclude_text"] = exclude_text }
	if type != none { options["type"] = type }
	if category != none { options["category"] = category }
	if flags != none { options["flags"] = flags }
	if moderation != none { options["moderation"] = moderation }
	if user_location != none { options["user_location"] = user_location }

	if contents == false {
		options.delete("contents")
	} else if contents == none && !options.contains("contents") {
		options["contents"] = {"text": {"max_characters": DEFAULT_MAX_CHARACTERS}}
	} else if contents != none {
		options["contents"] = contents
	}

	validate_search_options(options, SEARCH_OPTIONS_TYPES)
	options = to_camel_case(options)
	data := e.request("/search", options)
	cost_dollars := parse_cost_dollars(data.get("costDollars"))
	mut results := []Result{}
	for result in data["results"] {
		snake_result := to_snake_case(result)
		results.append(Result{
			url: snake_result.get("url")
			id: snake_result.get("id")
			title: snake_result.get("title")
			score: snake_result.get("score")
			published_date: snake_result.get("published_date")
			author: snake_result.get("author")
			image: snake_result.get("image")
			favicon: snake_result.get("favicon")
			subpages: snake_result.get("subpages")
			extras: snake_result.get("extras")
			text: snake_result.get("text")
			summary: snake_result.get("summary")
		})
	}
	return SearchResponse[Result]{
		results: results
		resolved_search_type: data.get("resolvedSearchType")
		auto_date: data.get("autoDate")
		cost_dollars: cost_dollars
	}
}

fn (e Exa) search_and_contents(query string, kwargs map[string]any) SearchResponse[Result] {
	options := {"query": query}
	for k, v in kwargs {
		if v != none {
			options[k] = v
		}
	}
	if !options.contains("text") && !options.contains("summary") && !options.contains("extras") {
		options["text"] = {"max_characters": DEFAULT_MAX_CHARACTERS}
	}
	mut merged_options := map[string][]string{}
	merged_options.update(SEARCH_OPTIONS_TYPES)
	merged_options.update(CONTENTS_OPTIONS_TYPES)
	merged_options.update(CONTENTS_ENDPOINT_OPTIONS_TYPES)
	validate_search_options(options, merged_options)
	if options.contains("summary") && options["summary"] is map[string]any {
		summary_opts := options["summary"]
		if summary_opts.contains("schema") {
			summary_opts["schema"] = exa_py.utils._convert_schema_input(summary_opts["schema"])
		}
	}
	options = nest_fields(options, ["text", "summary", "context", "subpages", "subpage_target", "livecrawl", "livecrawl_timeout", "extras"], "contents")
	options = to_camel_case(options, ["schema"])
	data := e.request("/search", options)
	cost_dollars := parse_cost_dollars(data.get("costDollars"))
	mut results := []Result{}
	for result in data["results"] {
		snake_result := to_snake_case(result)
		results.append(Result{
			url: snake_result.get("url")
			id: snake_result.get("id")
			title: snake_result.get("title")
			score: snake_result.get("score")
			published_date: snake_result.get("published_date")
			author: snake_result.get("author")
			image: snake_result.get("image")
			favicon: snake_result.get("favicon")
			subpages: snake_result.get("subpages")
			extras: snake_result.get("extras")
			text: snake_result.get("text")
			summary: snake_result.get("summary")
		})
	}
	return SearchResponse[Result]{
		results: results
		resolved_search_type: data.get("resolvedSearchType")
		auto_date: data.get("autoDate")
		context: data.get("context")
		cost_dollars: cost_dollars
	}
}

fn (e Exa) get_contents(urls any, kwargs map[string]any) SearchResponse[any] {
	mut url_list := []string{}
	if urls is string {
		url_list = [urls]
	} else if urls is []_Result {
		url_list = urls.map(it.url)
	} else {
		url_list = urls
	}
	options := {"urls": url_list}
	for k, v in kwargs {
		if k != "self" && v != none {
			options[k] = v
		}
	}
	if !options.contains("text") && !options.contains("summary") && !options.contains("extras") {
		options["text"] = {"max_characters": DEFAULT_MAX_CHARACTERS}
	}
	mut merged_options := map[string][]string{}
	merged_options.update(CONTENTS_OPTIONS_TYPES)
	merged_options.update(CONTENTS_ENDPOINT_OPTIONS_TYPES)
	validate_search_options(options, merged_options)
	if options.contains("summary") && options["summary"] is map[string]any {
		summary_opts := options["summary"]
		if summary_opts.contains("schema") {
			summary_opts["schema"] = exa_py.utils._convert_schema_input(summary_opts["schema"])
		}
	}
	options = to_camel_case(options, ["schema"])
	data := e.request("/contents", options)
	cost_dollars := parse_cost_dollars(data.get("costDollars"))
	mut statuses := []ContentStatus{}
	for status in data.get("statuses", []) {
		statuses.append(ContentStatus{
			id: status.get("id")
			status: status.get("status")
			source: status.get("source")
		})
	}
	mut results := []Result{}
	for result in data["results"] {
		snake_result := to_snake_case(result)
		results.append(Result{
			url: snake_result.get("url")
			id: snake_result.get("id")
			title: snake_result.get("title")
			score: snake_result.get("score")
			published_date: snake_result.get("published_date")
			author: snake_result.get("author")
			image: snake_result.get("image")
			favicon: snake_result.get("favicon")
			subpages: snake_result.get("subpages")
			extras: snake_result.get("extras")
			text: snake_result.get("text")
			summary: snake_result.get("summary")
		})
	}
	return SearchResponse[any]{
		results: results
		resolved_search_type: data.get("resolvedSearchType")
		auto_date: data.get("autoDate")
		context: data.get("context")
		cost_dollars: cost_dollars
		statuses: statuses
	}
}

