fn (ae AsyncExa) async_request(endpoint string, data any = none, method string = "POST", params map[string]any = none, headers map[string]string = none) any {
	needs_streaming := (data != none && data.get("stream")) || (params != none && params.get("stream") == "true")
	mut request_headers := ae.headers.clone()
	if headers != none {
		request_headers.update(headers)
	}
	mut res := none
	if method.to_upper() == "GET" {
		if needs_streaming {
			request := http.Request{
				method: "GET"
				url: ae.base_url + endpoint
				params: params
				headers: request_headers
			}
			res = ae.client.send(request, stream: true)
			return res
		} else {
			res = ae.client.get(ae.base_url + endpoint, params: params, headers: request_headers)
		}
	} else if method.to_upper() == "POST" {
		if needs_streaming {
			request := http.Request{
				method: "POST"
				url: ae.base_url + endpoint
				json: data
				headers: request_headers
			}
			res = ae.client.send(request, stream: true)
			return res
		} else {
			res = ae.client.post(ae.base_url + endpoint, json: data, headers: request_headers)
		}
	}
	if res.status_code != 200 && res.status_code != 201 {
		panic("Request failed with status code $res.status_code: $res.text")
	}
	return res.json()
}

