fn validate_search_options(options map[string]any, expected map[string][]string) {
	for key, value in options {
		if !expected.contains(key) {
			panic("Invalid option: '$key'")
		}
		if value == none {
			continue
		}
		expected_types := expected[key]
		valid := false
		for t in expected_types {
			if is_valid_type(value, t) {
				valid = true
				break
			}
		}
		if !valid {
			panic("Invalid value for option '$key': $value. Expected one of $expected_types")
		}
	}
}

