fn (e Exa) get_contents(urls any, kwargs map[string]any) SearchResponse[any] {
	mut url_list := []string{}
	if urls is string {
		url_list = [urls]
	} else if urls is []_Result {
		url_list = urls.map(it.url)
	} else {
		url_list = urls
	}
	options := {"urls": url_list}
	for k, v in kwargs {
		if k != "self" && v != none {
			options[k] = v
		}
	}
	if !options.contains("text") && !options.contains("summary") && !options.contains("extras") {
		options["text"] = {"max_characters": DEFAULT_MAX_CHARACTERS}
	}
	mut merged_options := map[string][]string{}
	merged_options.update(CONTENTS_OPTIONS_TYPES)
	merged_options.update(CONTENTS_ENDPOINT_OPTIONS_TYPES)
	validate_search_options(options, merged_options)
	if options.contains("summary") && options["summary"] is map[string]any {
		summary_opts := options["summary"]
		if summary_opts.contains("schema") {
			summary_opts["schema"] = exa_py.utils._convert_schema_input(summary_opts["schema"])
		}
	}
	options = to_camel_case(options, ["schema"])
	data := e.request("/contents", options)
	cost_dollars := parse_cost_dollars(data.get("costDollars"))
	mut statuses := []ContentStatus{}
	for status in data.get("statuses", []) {
		statuses.append(ContentStatus{
			id: status.get("id")
			status: status.get("status")
			source: status.get("source")
		})
	}
	mut results := []Result{}
	for result in data["results"] {
		snake_result := to_snake_case(result)
		results.append(Result{
			url: snake_result.get("url")
