fn (e Exa) wrap(client openai.OpenAI) openai.OpenAI {
	original_create := client.chat.completions.create
	client.chat.completions.create = fn(messages []openai.ChatCompletionMessageParam, model any, use_exa string = "auto", num_results int = 3, include_domains []string = none, exclude_domains []string = none, start_crawl_date string = none, end_crawl_date string = none, start_published_date string = none, end_published_date string = none, include_text []string = none, exclude_text []string = none, type string = none, category string = none, result_max_len int = 2048, flags []string = none, openai_kwargs map[string]any) ExaOpenAICompletion {
		exa_kwargs := {
			"num_results": num_results
			"include_domains": include_domains
			"exclude_domains": exclude_domains
			"start_crawl_date": start_crawl_date
			"end_crawl_date": end_crawl_date
			"start_published_date": start_published_date
			"end_published_date": end_published_date
			"include_text": include_text
			"exclude_text": exclude_text
			"type": type
			"category": category
			"flags": flags
		}
		create_kwargs := {"model": model}
		create_kwargs.update(openai_kwargs)
		return e._create_with_tool(original_create, messages, result_max_len, create_kwargs, exa_kwargs)
	}
	println("Wrapping OpenAI client with Exa functionality.")
	return client
}

fn (e Exa) _create_with_tool(create_fn fn(), messages []openai.ChatCompletionMessageParam, max_len int, create_kwargs map[string]any, exa_kwargs map[string]any) ExaOpenAICompletion {
	tools := [{
		"type": "function"
		"function": {
			"name": "search"
			"description": "Search the web for relevant information."
			"parameters": {
				"type": "object"
				"properties": {
					"query": {
						"type": "string"
						"description": "The query to search for."
					}
				}
				"required": ["query"]
			}
		}
	}]
	create_kwargs["tools"] = tools
	completion := create_fn(messages: messages, **create_kwargs)
	query := exa_py.utils.maybe_get_query(completion)
	if query == none {
		return ExaOpenAICompletion.from_completion(completion: completion, exa_result: none)
	}
	exa_result := e.search_and_contents(
		query: query
		num_results: exa_kwargs.get("num_results")
		include_domains: exa_kwargs.get("include_domains")
		exclude_domains: exa_kwargs.get("exclude_domains")
		start_crawl_date: exa_kwargs.get("start_crawl_date")
		end_crawl_date: exa_kwargs.get("end_crawl_date")
		start_published_date: exa_kwargs.get("start_published_date")
		end_published_date: exa_kwargs.get("end_published_date")
		include_text: exa_kwargs.get("include_text")
		exclude_text: exa_kwargs.get("exclude_text")
		type: exa_kwargs.get("type")
		category: exa_kwargs.get("category")
		flags: exa_kwargs.get("flags")
	)
	exa_str := exa_py.utils.format_exa_result(exa_result, max_len: max_len)
	new_messages := exa_py.utils.add_message_to_messages(completion, messages, exa_str)
	completion = create_fn(messages: new_messages, **create_kwargs)
	exa_completion := ExaOpenAICompletion.from_completion(completion: completion, exa_result: exa_result)
	return exa_completion
}

fn (e Exa) answer(query string, stream bool = false, text bool = false, system_prompt string = none, model string = none, output_schema any = none, user_location string = none) any {
	if stream {
		panic("stream=True is not supported in `answer()`. Please use `stream_answer(...)` for streaming.")
	}
	mut options := map[string]any{}
	if query != none { options["query"] = query }
	if stream != none { options["stream"] = stream }
	if text != none { options["text"] = text }
	if system_prompt != none { options["system_prompt"] = system_prompt }
	if model != none { options["model"] = model }
	if output_schema != none { options["output_schema"] = output_schema }
	if user_location != none { options["user_location"] = user_location }

	if options.contains("output_schema") && options["output_schema"] != none {
		options["output_schema"] = exa_py.utils._convert_schema_input(options["output_schema"])
	}

	options = to_camel_case(options, ["output_schema"])
	response := e.request("/answer", options)
	mut citations := []AnswerResult{}
	for result in response["citations"] {
		snake_result := to_snake_case(result)
		citations.append(AnswerResult{
			id: snake_result.get("id")
			url: snake_result.get("url")
			title: snake_result.get("title")
			published_date: snake_result.get("published_date")
			author: snake_result.get("author")
			text: snake_result.get("text")
		})
	}
	return AnswerResponse{answer: response["answer"], citations: citations}
}

fn (e Exa) stream_answer(query string, text bool = false, system_prompt string = none, model string = none, output_schema any = none, user_location string = none) StreamAnswerResponse {
	mut options := map[string]any{}
	if query != none { options["query"] = query }
	if text != none { options["text"] = text }
	if system_prompt != none { options["system_prompt"] = system_prompt }
	if model != none { options["model"] = model }
	if output_schema != none { options["output_schema"] = output_schema }
	if user_location != none { options["user_location"] = user_location }

	if options.contains("output_schema") && options["output_schema"] != none {
		options["output_schema"] = exa_py.utils._convert_schema_input(options["output_schema"])
	}

	options = to_camel_case(options, ["output_schema"])
	options["stream"] = true
	raw_response := e.request("/answer", options)
	return StreamAnswerResponse{_raw_response: raw_response}
}

struct AsyncExa {
	Exa
	_client http.Client
}

fn new_async_exa(api_key string, api_base string = "") AsyncExa {
	base_exa := new_exa(api_key, api_base)
	return AsyncExa{
		Exa: base_exa
		_client: none
		research: new_async_research_client()
		websets: new_async_websets_client()
	}
}

fn (ae AsyncExa) client() http.Client {
	if ae._client == none {
		ae._client = http.Client{
			base_url: ae.base_url
			headers: ae.headers
			timeout: 600
		}
	}
	return ae._client
}

fn (ae AsyncExa) async_request(endpoint string, data any = none, method string = "POST", params map[string]any = none, headers map[string]string = none) any {
	needs_streaming := (data != none && data.get("stream")) || (params != none && params.get("stream") == "true")
	mut request_headers := ae.headers.clone()
	if headers != none {
		request_headers.update(headers)
	}
	mut res := none
	if method.to_upper() == "GET" {
		if needs_streaming {
			request := http.Request{
				method: "GET"
				url: ae.base_url + endpoint
				params: params
				headers: request_headers
			}
			res = ae.client.send(request, stream: true)
			return res
		} else {
			res = ae.client.get(ae.base_url + endpoint, params: params, headers: request_headers)
		}
	} else if method.to_upper() == "POST" {
		if needs_streaming {
			request := http.Request{
				method: "POST"
				url: ae.base_url + endpoint
				json: data
				headers: request_headers
			}
			res = ae.client.send(request, stream: true)
			return res
		} else {
			res = ae.client.post(ae.base_url + endpoint, json: data, headers: request_headers)
		}
	}
	if res.status_code != 200 && res.status_code != 201 {
		panic("Request failed with status code $res.status_code: $res.text")
	}
	return res.json()
}

fn (ae AsyncExa) search(query string, contents any = none, num_results int = none, include_domains []string = none, exclude_domains []string = none, start_crawl_date string = none, end_crawl_date string = none, start_published_date string = none, end_published_date string = none, include_text []string = none, exclude_text []string = none, type string = none, category string = none, flags []string = none, moderation bool = none, user_location string = none) SearchResponse[Result] {
	mut options := map[string]any{}
	if query != none { options["query"] = query }
	if contents != none { options["contents"] = contents }
	if num_results != none { options["num_results"] = num_results }
	if include_domains != none { options["include_domains"] = include_domains }
	if exclude_domains != none { options["exclude_domains"] = exclude_domains }
	if start_crawl_date != none { options["start_crawl_date"] = start_crawl_date }
